/**
 * Check every one of the verified servers, not just the hand-written apps.
 *
 *   node "MCP Hub/scripts/verify-verified.mjs"
 *
 * `verify-catalog.mjs` guards the 108 curated apps. It never opens the verified catalog,
 * which is the part that actually grows: 8,094 servers, generated by three scripts from a
 * registry snapshot and two live passes. A generator bug therefore reaches users as
 * thousands of broken cards at once, and nothing in the repo would have caught it. Two did,
 * in fact — every `url_input` row was marked dead by a probe that had no URL to send, and
 * every browser app was reported as needing a client ID because the registration endpoint
 * was never followed to its issuer. Neither failed a typecheck.
 *
 * This is the gate for that layer. It reads only what ships — the generated modules and the
 * seed catalog — with no network and no credentials, and it fails on the first inconsistency.
 * The checks are the invariants the panel relies on, so a green run means the panel's
 * assumptions hold for every row:
 *
 *   1. The index and the detail map are both loadable and agree with each other.
 *   2. Every row has a connect kind that maps to a flow the panel can actually run.
 *   3. Every row that asks for a value can say where to get it, or is explicitly allowed not to.
 *   4. Every row carries a name, a category and a verification level from the known sets.
 *   5. Ids are unique, and the declared row count matches the rows on disk.
 *   6. Every URL and template is well formed.
 */

import { readFile } from "node:fs/promises"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

const HERE = dirname(fileURLToPath(import.meta.url))
const CATALOG = join(HERE, "..", "catalog")

const errors = []
const notes = []
const fail = (id, message) => errors.push(`${id}: ${message}`)

const CONNECT_KINDS = new Set(["no_auth", "oauth_browser", "api_key", "url_input", "unknown"])
const INSTALL_KINDS = new Set(["remote_http", "npx", "uvx", "docker", "mcpb", "nuget", "unknown"])
const VERIFICATIONS = new Set(["full", "tools_list", "auth_discovery", "launched", "declared", "unknown"])

/**
 * Read a generated module without importing it.
 *
 * The index is 1.2 MB of a single array literal and the detail map is a JSON object literal.
 * Importing either would execute the module and pull in the whole TypeScript loader; taking
 * the literal out of the text and parsing it is faster and works the same way the panel's
 * own dynamic import resolves it. The brace/bracket walk respects string literals, so a `}`
 * inside a description cannot end the literal early.
 */
function literalIn(text, marker, open, close) {
  const at = text.indexOf(marker)
  if (at === -1) throw new Error(`marker not found: ${marker}`)
  const start = text.indexOf(open, at + marker.length)
  if (start === -1) throw new Error(`opening ${open} not found after ${marker}`)
  let depth = 0
  let inString = false
  let escaped = false
  for (let i = start; i < text.length; i++) {
    const c = text[i]
    if (inString) {
      if (escaped) escaped = false
      else if (c === "\\") escaped = true
      else if (c === '"') inString = false
      continue
    }
    if (c === '"') inString = true
    else if (c === open) depth++
    else if (c === close) {
      depth--
      if (depth === 0) return JSON.parse(text.slice(start, i + 1))
    }
  }
  throw new Error(`unterminated literal after ${marker}`)
}

const indexText = await readFile(join(CATALOG, "verified-index.ts"), "utf8")
const detailText = await readFile(join(CATALOG, "connect-detail.ts"), "utf8")

const rows = literalIn(indexText, "export const verifiedRows: VerifiedRow[] = ", "[", "]")
const declaredCount = Number(indexText.match(/export const verifiedRowCount = (\d+)/)?.[1])
const details = literalIn(detailText, "export const connectDetails: Record<string, ConnectDetail> = ", "{", "}")

// 5. the count the module advertises is the count it holds.
if (declaredCount !== rows.length) {
  fail("verified-index", `verifiedRowCount says ${declaredCount} but ${rows.length} rows are present`)
}

const ids = new Set()
const byKind = {}
const asked = { env: 0, urlTemplate: 0, clientId: 0, apiKey: 0 }
const linked = { env: 0, urlTemplate: 0, clientId: 0, apiKey: 0 }

const looksLikeUrl = (value) => /^https?:\/\/[^\s]+$/i.test(value)
const hasPlaceholder = (value) => /\{[^}]+\}/.test(value)

for (const row of rows) {
  if (!Array.isArray(row) || row.length !== 14) {
    fail(String(row?.[0] ?? "row"), `expected 14 fields, found ${Array.isArray(row) ? row.length : "not an array"}`)
    continue
  }
  const [id, name, category, installKind, connectKind, verification, toolCount, needsLogin, url, pkgType, pkgId, pkgVersion, website, repository] = row

  // 5. ids are the handle for everything else.
  if (ids.has(id)) fail(id, "duplicate id in the index")
  ids.add(id)

  // 2. a connect kind the panel has no flow for is a card that cannot be pressed.
  if (!CONNECT_KINDS.has(connectKind)) fail(id, `unknown connect_kind "${connectKind}"`)
  if (!INSTALL_KINDS.has(installKind)) fail(id, `unknown install_kind "${installKind}"`)
  if (!VERIFICATIONS.has(verification)) fail(id, `unknown verification "${verification}"`)

  if (!name?.trim()) fail(id, "missing name")
  if (!category?.trim()) fail(id, "missing category")
  if (typeof toolCount !== "number" || toolCount < 0) fail(id, `tool_count ${toolCount} is not a count`)
  if (needsLogin !== 0 && needsLogin !== 1) fail(id, `needs_login ${needsLogin} is not 0 or 1`)

  byKind[connectKind] = (byKind[connectKind] ?? 0) + 1

  // 6. every endpoint is a URL, or a template that becomes one once the user fills it in.
  if (url && !looksLikeUrl(url) && !hasPlaceholder(url)) fail(id, `url "${url}" is neither a URL nor a template`)
  if (website && !looksLikeUrl(website)) fail(id, `website "${website}" is not a URL`)
  if (repository && !looksLikeUrl(repository)) fail(id, `repository "${repository}" is not a URL`)

  // A local row is launched from a package; a remote one is reached at a URL. A row with
  // neither is a card whose Connect button has nothing to do.
  const isRemote = installKind === "remote_http"
  if (isRemote && !url) fail(id, "remote row with no endpoint")
  if (!isRemote && (!pkgType || !pkgId)) fail(id, `local row (${installKind}) with no package to launch`)

  const detail = details[id]

  // 3. every row that asks for a value must be able to say where to get it.
  if (detail) {
    if (detail.env?.length) {
      asked.env++
      for (const variable of detail.env) {
        if (!variable.name?.trim()) fail(id, "environment variable with no name")
      }
      // A form box is only useful if it says where the value comes from; either the
      // variable carries its own page, or the row carries one for the whole form.
      if (detail.env.some((v) => v.url) || detail.consoleUrl) linked.env++
      else fail(id, "asks for environment variables but offers no page to get them from")
    }

    if (detail.urlTemplate) {
      asked.urlTemplate++
      if (!hasPlaceholder(detail.urlTemplate)) fail(id, "urlTemplate has no placeholder to fill")
      linked.urlTemplate++ // the user's own address; there is no vendor page to link
    }

    if (connectKind === "oauth_browser" && detail.selfRegisters === false) {
      asked.clientId++
      if (detail.consoleUrl) linked.clientId++
      else fail(id, "needs a client ID but names no console to create one in")
    }

    if (connectKind === "api_key") {
      asked.apiKey++
      if (detail.consoleUrl) linked.apiKey++
      else fail(id, "asks for a key but names no page that issues one")
    }
  } else if (connectKind === "api_key") {
    // An api_key row with no detail at all has no form and no link — the card would ask
    // for a key it can neither collect nor explain.
    fail(id, "api_key row with no connect detail")
  }

  if (connectKind === "url_input" && !(detail?.urlTemplate || hasPlaceholder(url))) {
    fail(id, "url_input row with no template to complete")
  }
  if (connectKind === "oauth_browser" && detail?.selfRegisters !== true && detail?.selfRegisters !== false) {
    // Not fatal on its own, but the panel then falls back to the consoleUrl heuristic, so
    // it is worth knowing how many rows are in that state.
    notes.push(`${id}: browser app with no measured registration verdict`)
  }
}

// 1. the detail map only describes rows that exist; an orphan is a stale entry.
for (const id of Object.keys(details)) {
  if (!ids.has(id)) fail(id, "connect detail for a row that is not in the index")
}

// The seed catalog the panel opens with must stay loadable alongside the generated one.
const seedText = await readFile(join(CATALOG, "seed.ts"), "utf8")
if (!seedText.includes("allSeedApps")) fail("seed", "allSeedApps is missing")

const summary = {
  rows: rows.length,
  details: Object.keys(details).length,
  byConnectKind: byKind,
  asksFor: asked,
  withPage: linked,
  unmeasuredRegistrationVerdicts: notes.length,
}

process.stdout.write(`MCP Hub verified catalog — ${rows.length} servers\n`)
process.stdout.write(`  ${Object.entries(byKind).map(([k, n]) => `${k} ${n}`).join("  ")}\n`)
process.stdout.write(
  `  needs a value: env ${asked.env}, instance ${asked.urlTemplate}, client id ${asked.clientId}, key ${asked.apiKey}\n`,
)
process.stdout.write(
  `  can say where to get it: env ${linked.env}, instance ${linked.urlTemplate}, client id ${linked.clientId}, key ${linked.apiKey}\n`,
)

if (notes.length > 0 && process.env.MCP_HUB_VERBOSE === "1") {
  process.stdout.write(`  ${notes.length} rows fall back to the console heuristic:\n`)
  for (const note of notes.slice(0, 40)) process.stdout.write(`    ${note}\n`)
}

if (errors.length > 0) {
  process.stderr.write(`\n${errors.length} problem${errors.length === 1 ? "" : "s"}:\n`)
  for (const error of errors.slice(0, 60)) process.stderr.write(`  ${error}\n`)
  if (errors.length > 60) process.stderr.write(`  … and ${errors.length - 60} more\n`)
  process.exit(1)
}

process.stdout.write("\nevery verified row is well formed and has a flow to connect it\n")
process.stdout.write(JSON.stringify(summary, null, 2) + "\n")
